// Shared computed figures for ISC 11 Accounts ch07 (Trial Balance): the worked cases of the decks. Imagined firms only.
// Every amount is generated by tb.mjs/acc.mjs and asserted here. Question items compute their own figures beside the item.
import { same, check, sum, journal, post, trialFromLedgers, fromBalances, withCapital, errorCase, swap, accountTotals } from './tb.mjs';
export * from './tb.mjs';

// ---------------------------------------------------------------- Kasaragod Spice Traders: a simple trial balance
export const KS_ITEMS = [
  ['Cash in hand', 14500, 'asset'], ['Cash at bank', 126000, 'asset'], ['Debtors', 84000, 'debtor'], ['Furniture', 55000, 'asset'], ['Machinery', 240000, 'asset'],
  ['Purchases', 410000, 'purchases'], ['Wages', 38000, 'expense'], ['Rent', 30000, 'expense'], ['Salaries', 72000, 'expense'], ['Drawings', 36000, 'drawings'],
  ['Sales', 625000, 'sales'], ['Creditors', 105000, 'creditor'], ['Capital', 375500, 'capital'],
];
export const KS = fromBalances(KS_ITEMS);
same(KS.dr, 1105500, 'Kasaragod trial balance total');

// ---------------------------------------------------------------- Padmini Dry Fruits: books used for the error cases
export const PD = {
  capital: { dr: [['Cash', 300000]], cr: [['Capital', 300000]], note: 'Capital brought in by the proprietor' },
  furniture: { dr: [['Furniture', 40000]], cr: [['Cash', 40000]], note: 'Furniture bought for cash' },
  computer: { dr: [['Computer', 36000]], cr: [['Cash', 36000]], note: 'Computer bought for cash' },
  pur1: { dr: [['Purchases', 120000]], cr: [['Sundar Nuts Co.', 120000]], note: 'Goods bought on credit' },
  pur2: { dr: [['Purchases', 45000]], cr: [['Ellora Foods', 45000]], note: 'Goods bought on credit' },
  sale1: { dr: [['Tamil Stores', 90000]], cr: [['Sales', 90000]], note: 'Goods sold on credit' },
  sale2: { dr: [['Cash', 50000]], cr: [['Sales', 50000]], note: 'Goods sold for cash' },
  receipt: { dr: [['Cash', 60000]], cr: [['Tamil Stores', 60000]], note: 'Cash received from Tamil Stores' },
  paySun: { dr: [['Sundar Nuts Co.', 70000]], cr: [['Cash', 70000]], note: 'Cash paid to Sundar Nuts Co.' },
  payEll: { dr: [['Ellora Foods', 15000]], cr: [['Cash', 15000]], note: 'Cash paid to Ellora Foods' },
  rent: { dr: [['Rent', 12000]], cr: [['Cash', 12000]], note: 'Rent paid' },
  comm: { dr: [['Cash', 8000]], cr: [['Commission received', 8000]], note: 'Commission received' },
  sale3: { dr: [['Tamil Stores', 22000]], cr: [['Sales', 22000]], note: 'Goods sold on credit' },
};
export const PD_LIST = Object.values(PD);
journal(PD_LIST); // every entry of the correct books balances
export const PD_TB = trialFromLedgers(post(PD_LIST));
same(PD_TB.dr, 550000, 'Padmini correct trial balance total');

const one = (dr, cr, note) => ({ dr, cr, note });
// Errors that leave the totals equal.
export const PD_OMIT = errorCase({ right: PD_LIST, wrong: swap(PD, { sale3: null }), agrees: true });
export const PD_PRINC = errorCase({ right: PD_LIST, wrong: swap(PD, { computer: one([['Purchases', 36000]], [['Cash', 36000]], 'Computer debited to Purchases') }), agrees: true });
export const PD_COMM = errorCase({ right: PD_LIST, wrong: swap(PD, { payEll: one([['Sundar Nuts Co.', 15000]], [['Cash', 15000]], 'Payment debited to the wrong creditor') }), agrees: true });
export const PD_COMP = errorCase({
  right: PD_LIST,
  wrong: swap(PD, { rent: one([['Rent', 21000]], [['Cash', 12000]], 'Rent debited too much'), comm: one([['Cash', 8000]], [['Commission received', 17000]], 'Commission credited too much') }),
  agrees: true,
});
same(PD_OMIT.bad.dr, 528000, 'omission leaves totals equal at');
same(PD_PRINC.bad.dr, 550000, 'principle error leaves totals equal at');
same(PD_COMP.bad.dr, 559000, 'compensating errors leave totals equal at');
// Errors that disturb the totals.
export const PD_ONE = errorCase({ right: PD_LIST, wrong: swap(PD, { receipt: one([['Cash', 60000]], [], 'Credit to Tamil Stores left out') }), agrees: false });
export const PD_AMT = errorCase({ right: PD_LIST, wrong: swap(PD, { pur2: one([['Purchases', 54000]], [['Ellora Foods', 45000]], 'Purchases debited with a wrong amount') }), agrees: false });
export const PD_TWICE = errorCase({ right: PD_LIST, wrong: swap(PD, { rent: one([['Rent', 12000], ['Cash', 12000]], [], 'Rent paid debited to Cash as well') }), agrees: false });
export const PD_CR2 = errorCase({ right: PD_LIST, wrong: swap(PD, { sale2: one([['Cash', 50000]], [['Sales', 50000], ['Sales', 50000]], 'Cash sale credited to Sales twice') }), agrees: false });
same(PD_ONE.gap, 60000, 'one-sided posting gap');
same(PD_AMT.gap, 9000, 'wrong amount gap');
same(PD_TWICE.gap, 24000, 'two debits gap');
same(PD_CR2.gap, -50000, 'double credit gap');

// ---------------------------------------------------------------- Wardha Hosiery: deciding the side of each balance
export const WH_ITEMS = [
  ['Opening stock', 68000, 'openingStock'], ['Purchases', 540000, 'purchases'], ['Purchases return', 12000, 'returnsOut'], ['Sales', 820000, 'sales'], ['Sales return', 20000, 'returnsIn'],
  ['Carriage inwards', 9000, 'expense'], ['Wages', 46000, 'expense'], ['Salaries', 84000, 'expense'], ['Bad debts', 6000, 'loss'], ['Provision for doubtful debts', 8000, 'provision'],
  ['Discount allowed', 5000, 'expense'], ['Discount received', 7000, 'income'], ['Debtors', 110000, 'debtor'], ['Creditors', 95000, 'creditor'], ['Bills payable', 25000, 'liability'],
  ['Plant and machinery', 280000, 'asset'], ['Drawings', 40000, 'drawings'], ['Bank overdraft', 30000, 'liability'], ['Cash in hand', 10000, 'asset'], ['Capital', 221000, 'capital'],
  ['Closing stock', 74000, 'closingStock'],
];
export const WH = fromBalances(WH_ITEMS);
same(WH.dr, 1218000, 'Wardha trial balance total');
same(WH.outside.length, 1, 'Wardha closing stock is outside');

// ---------------------------------------------------------------- Rohtak: missing capital
export const RK_ITEMS = [
  ['Cash in hand', 8500, 'asset'], ['Cash at bank', 64000, 'asset'], ['Debtors', 132000, 'debtor'], ['Opening stock', 55000, 'openingStock'], ['Land and building', 450000, 'asset'],
  ['Furniture', 36000, 'asset'], ['Purchases', 310000, 'purchases'], ['Salaries', 60000, 'expense'], ['Insurance', 9000, 'expense'], ['Drawings', 25000, 'drawings'], ['Interest on loan', 7500, 'expense'],
  ['Sales', 480000, 'sales'], ['Creditors', 70000, 'creditor'], ['Bank loan', 150000, 'liability'], ['Commission received', 12000, 'income'],
];
export const RK = withCapital(RK_ITEMS);
same(RK.capital, 445000, 'Rohtak missing capital');
same(RK.dr, 1157000, 'Rohtak trial balance total');

// ---------------------------------------------------------------- Palampur Woollens: ledgers from transactions
export const PW = [
  { date: '1 Jan', dr: [['Cash', 200000], ['Furniture', 30000]], cr: [['Capital', 230000]], note: 'Business started with cash and furniture' },
  { date: '2 Jan', dr: [['Purchases', 60000]], cr: [['Cash', 60000]], note: 'Goods bought for cash' },
  { date: '5 Jan', dr: [['Purchases', 90000]], cr: [['Gill Wool Mills', 90000]], note: 'Goods bought on credit' },
  { date: '9 Jan', dr: [['Dhiman Retail', 75000]], cr: [['Sales', 75000]], note: 'Goods sold on credit' },
  { date: '12 Jan', dr: [['Cash', 40000]], cr: [['Sales', 40000]], note: 'Goods sold for cash' },
  { date: '15 Jan', dr: [['Rent', 8000]], cr: [['Cash', 8000]], note: 'Rent paid' },
  { date: '18 Jan', dr: [['Cash', 50000]], cr: [['Dhiman Retail', 50000]], note: 'Cash received from Dhiman Retail' },
  { date: '22 Jan', dr: [['Gill Wool Mills', 55000]], cr: [['Cash', 55000]], note: 'Cash paid to Gill Wool Mills' },
  { date: '25 Jan', dr: [['Salaries', 14000]], cr: [['Cash', 14000]], note: 'Salaries paid' },
  { date: '28 Jan', dr: [['Drawings', 10000]], cr: [['Cash', 10000]], note: 'Cash withdrawn by the proprietor' },
];
export const PW_J = journal(PW);
